# Health check script for Base 1
# Checks required directories, ports, and Ollama/qwen2.5 service.

function Test-PortOpen($port) {
    try {
        $tcpClient = New-Object System.Net.Sockets.TcpClient
        $result = $tcpClient.BeginConnect('127.0.0.1', $port, $null, $null)
        $success = $result.AsyncWaitHandle.WaitOne(1000, $false)
        if (-not $success) { return $false }
        $tcpClient.EndConnect($result) | Out-Null
        $tcpClient.Close()
        return $true
    } catch { return $false }
}

function Test-Ollama {
    try {
        $response = Invoke-RestMethod -Uri 'http://localhost:11434/api/tags' -TimeoutSec 2 -ErrorAction Stop
        return $true
    } catch { return $false }
}

# Define required paths (relative to script location)
$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Definition
$requiredPaths = @(
    Join-Path $scriptDir '..\..\..\MQL4\Experts'
    Join-Path $scriptDir '..\..\..\MQL5\Indicators'
    Join-Path $scriptDir '..\mission-control-app'
    Join-Path $scriptDir '.env'
)

Write-Host "=== Base 1 Health Check ===" -ForegroundColor Cyan

# Check directories/files
foreach ($path in $requiredPaths) {
    if (Test-Path -Path $path) {
        Write-Host "[OK]  $path" -ForegroundColor Green
    } else {
        Write-Host "[FAIL] $path" -ForegroundColor Red
    }
}

# Check ports
$portsToCheck = @(18789) # OpenClaw UI; add others if known
foreach ($port in $portsToCheck) {
    if (Test-PortOpen -port $port) {
        Write-Host "[OK]  Port $port listening" -ForegroundColor Green
    } else {
        Write-Host "[FAIL] Port $port not listening" -ForegroundColor Red
    }
}

# Check Ollama/qwen2.5
if (Test-Ollama) {
    Write-Host "[OK]  Ollama/qwen2.5 service responding" -ForegroundColor Green
} else {
    Write-Host "[FAIL] Ollama/qwen2.5 not responding" -ForegroundColor Red
}

Write-Host "===========================" -ForegroundColor Cyan","path":"C:\Users\MikeT\Projects\Chief Madithi\base1_status.ps1"}

